import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"战斗信息","description":"","frontmatter":{},"headers":[],"relativePath":"feature/combat.md","filePath":"feature/combat.md","lastUpdated":1792924908000}`),a={name:`feature/combat.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="战斗信息" tabindex="-1">战斗信息 <a class="header-anchor" href="#战斗信息" aria-label="Permalink to “战斗信息”">​</a></h1><p>战斗信息展示当前战斗的 BOSS、角色、伤害与参战玩家数据。</p><h2 id="boss信息" tabindex="-1">BOSS信息 <a class="header-anchor" href="#boss信息" aria-label="Permalink to “BOSS信息”">​</a></h2><p><img src="/tarou-docs/assets/img/combat-img1.png" alt="alt text" width="1678" height="1508"></p><h2 id="数据统计" tabindex="-1">数据统计 <a class="header-anchor" href="#数据统计" aria-label="Permalink to “数据统计”">​</a></h2><p><img src="/tarou-docs/assets/img/combat-img2.png" alt="alt text" width="2920" height="1398"></p><h3 id="角色状态" tabindex="-1">角色状态 <a class="header-anchor" href="#角色状态" aria-label="Permalink to “角色状态”">​</a></h3><p>显示角色的全部状态信息，头像区域显示护盾值，点击状态图标可以设为标记状态放大显示，也可以只显示标记状态。</p><h3 id="伤害统计" tabindex="-1">伤害统计 <a class="header-anchor" href="#伤害统计" aria-label="Permalink to “伤害统计”">​</a></h3><p>实时统计战斗过程中各个角色造成的伤害，同样分为普攻、技伤、奥伤和其他，同时还统计了角色连击情况。</p><p>巴布塔支持三队成员统计，切队后继续累计各角色的数据；角色状态可在当前出战队与全部成员之间切换。</p><h3 id="承伤统计" tabindex="-1">承伤统计 <a class="header-anchor" href="#承伤统计" aria-label="Permalink to “承伤统计”">​</a></h3><p>实时统计战斗过程中各个角色受到的伤害，分为普攻、特动和其他。</p><h2 id="攻击信息" tabindex="-1">攻击信息 <a class="header-anchor" href="#攻击信息" aria-label="Permalink to “攻击信息”">​</a></h2><p><img src="/tarou-docs/assets/img/combat-img3.png" alt="alt text" width="310" height="74"></p><p>展示最近一次按下<code>攻击按钮</code>时造成的伤害统计，之前按的技能都不在统计范围内。主要是为了判断当前攻击是否达到特动解除条件。</p><h2 id="玩家信息" tabindex="-1">玩家信息 <a class="header-anchor" href="#玩家信息" aria-label="Permalink to “玩家信息”">​</a></h2><p><img src="/tarou-docs/assets/img/combat-img4.png" alt="alt text" width="420" height="385"></p><p>展示当前副本战斗中的所有玩家信息，红框代表自己，绿框代表房主。</p><p>右上角会记录玩家发过的表情，方便高难表情计数。目前只展示女路人和维拉的hi表情，有人第二次发hi时重置之前的记录。如果有人乱发的表情，也可以通过点击表情的方式重置所有表情。</p><p><img src="/tarou-docs/assets/img/combat-img5.png" alt="alt text" width="232" height="230"></p><p>鼠标悬浮在玩家卡片上，会显示两个操作按钮，左边是打开该玩家首页，右边是标记该玩家。如果已经标记过，就会显示备注，卡片右下方也会显示书签标识。</p><p><img src="/tarou-docs/assets/img/combat-img6.png" alt="alt text" width="324" height="71"></p><p>已读取战斗记录且处于共斗房间时，顶部会展示房间成员信息；进入战斗后房间成员区域隐藏，展示参战玩家列表。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><img src="/tarou-docs/assets/img/combat-img7.png" alt="alt text" width="300" height="120"></p><p>排名和贡献信息需要开启游戏中的实时通知。</p></div><p><span id="战斗面板"></span></p><h2 id="战斗弹窗" tabindex="-1">战斗弹窗 <a class="header-anchor" href="#战斗弹窗" aria-label="Permalink to “战斗弹窗”">​</a></h2><p>桌面与扩展点击BOSS信息中的BOSS名称可以打开独立战斗浮窗，展示更为详细的战斗数据。各个信息面板都可以开关和拖动改变位置，可以根据自己的使用习惯布置界面。移动端没有独立战斗浮窗。</p>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};